// Prepare scoring prompt
const input = $input.first().json.body || $input.first().json;

const scoringPrompt = `You just had a dating conversation as ${input.scorer_name} with ${input.target_name}.

Here is the full conversation:
${(input.messages || []).map(m => `${m.name}: ${m.content}`).join('\n')}

Your profile:
${input.scorer_summary || ''}

Their profile:
${input.target_summary || ''}

Rate your compatibility with ${input.target_name} on these dimensions (each 0.0 to 10.0):

1. shared_interests - How much do your hobbies and interests overlap?
2. communication_style - How well did your conversational styles mesh?
3. lifestyle_alignment - How compatible are your daily routines and lifestyle?
4. intellectual_match - How stimulating was the intellectual connection?
5. ambition_alignment - How aligned are your career drives and goals?
6. emotional_resonance - How emotionally compatible do you feel?
7. creative_compatibility - How well do your creative/artistic sides match?
8. energy_match - How well do your energy levels complement each other?

Also provide:
- overall_score: A weighted average (0.0-10.0)
- reasoning: 2-3 sentences explaining your assessment

Respond ONLY with a JSON object with these exact keys. No markdown.`;

return {
  json: {
    ...input,
    scoring_prompt: scoringPrompt
  }
};

// Parse score and store
const aiResponse = $input.first().json;
const input = $('Prepare Scoring Prompt').first().json;

let scores;
try {
  const content = typeof aiResponse.message?.content === 'string' 
    ? aiResponse.message.content 
    : JSON.stringify(aiResponse);
  scores = JSON.parse(content.replace(/```json\n?|```\n?/g, ''));
} catch (e) {
  scores = {
    shared_interests: 5,
    communication_style: 5,
    lifestyle_alignment: 5,
    intellectual_match: 5,
    ambition_alignment: 5,
    emotional_resonance: 5,
    creative_compatibility: 5,
    energy_match: 5,
    overall_score: 5,
    reasoning: 'Unable to parse AI response'
  };
}

return {
  json: {
    date_id: input.date_id,
    scorer_id: input.scorer_id,
    target_id: input.target_id,
    shared_interests: scores.shared_interests || 0,
    communication_style: scores.communication_style || 0,
    lifestyle_alignment: scores.lifestyle_alignment || 0,
    intellectual_match: scores.intellectual_match || 0,
    ambition_alignment: scores.ambition_alignment || 0,
    emotional_resonance: scores.emotional_resonance || 0,
    creative_compatibility: scores.creative_compatibility || 0,
    energy_match: scores.energy_match || 0,
    overall_score: scores.overall_score || 0,
    reasoning: scores.reasoning || ''
  }
};
